CREATE ALGORITHM=UNDEFINED DEFINER=`root`@`localhost` SQL SECURITY DEFINER VIEW `cte_area_by_water_shortage` AS with `area_shortage` as (select `a`.`Area_name` AS `Area_name`,sum(`s`.`Shortage_hours`) AS `total_shortage` from (`areas` `a` join `supply_daily` `s` on((`a`.`Area_id` = `s`.`Area_id`))) group by `a`.`Area_name`) select `area_shortage`.`Area_name` AS `Area_name`,`area_shortage`.`total_shortage` AS `Total_shortage`,rank() OVER (ORDER BY `area_shortage`.`total_shortage` desc )  AS `Shortage_rank` from `area_shortage`;

CREATE ALGORITHM=UNDEFINED DEFINER=`root`@`localhost` SQL SECURITY DEFINER VIEW `area_risk_summary` AS with `supply` as (select `supply_daily`.`Area_id` AS `Area_id`,round(sum(`supply_daily`.`Shortage_hours`),1) AS `shortage_hours` from `supply_daily` group by `supply_daily`.`Area_id`), `tanker` as (select `tanker_orders`.`Area_id` AS `Area_id`,count(0) AS `tanker_orders`,sum(`tanker_orders`.`Amount_inr`) AS `tanker_expense` from `tanker_orders` group by `tanker_orders`.`Area_id`), `complaint_data` as (select `complaints`.`Area_id` AS `Area_id`,count(0) AS `total_complaints` from `complaints` group by `complaints`.`Area_id`) select `a`.`Area_name` AS `area_name`,`s`.`shortage_hours` AS `shortage_hours`,`t`.`tanker_orders` AS `tanker_orders`,`t`.`tanker_expense` AS `tanker_expense`,`c`.`total_complaints` AS `total_complaints` from (((`areas` `a` left join `supply` `s` on((`a`.`Area_id` = `s`.`Area_id`))) left join `tanker` `t` on((`a`.`Area_id` = `t`.`Area_id`))) left join `complaint_data` `c` on((`a`.`Area_id` = `c`.`Area_id`))) order by `s`.`shortage_hours` desc;

