CREATE ALGORITHM=UNDEFINED DEFINER=`root`@`localhost` SQL SECURITY DEFINER VIEW `tanker_delivery_performance` AS select `tanker_orders`.`Tanker_provider_type` AS `Tanker_provider_type`,count(0) AS `total_orders`,sum((case when (`tanker_orders`.`Delivery_status` = 'Delivered') then 1 else 0 end)) AS `Successful_deliveries`,round(((100.0 * sum((case when (`tanker_orders`.`Delivery_status` = 'Delivered') then 1 else 0 end))) / count(0)),2) AS `Delivery_success_pct` from `tanker_orders` group by `tanker_orders`.`Tanker_provider_type`;

